result:
**The bug:** The condition `decoded.exp < Date.now() / 1000` uses strict less-than, so when `exp === now` the check passes and the token is accepted. It should be `<=`.

**The deeper issue:** `jwt.verify()` already validates expiry and throws `TokenExpiredError` when expired — so the manual check is both redundant and buggy. The fix is to remove it and handle the error types properly instead.

```javascript
const jwt = require('jsonwebtoken');

function authMiddleware(req, res, next) {
  const token = req.headers.authorization?.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'No token provided' });
  }

  if (!process.env.JWT_SECRET) {
    return res.status(500).json({ error: 'Server misconfiguration' });
  }

  try {
    // jwt.verify rejects tokens where exp <= now, covering the boundary case
    const decoded = jwt.verify(token, process.env.JWT_SECRET);
    req.user = decoded;
    next();
  } catch (err) {
    if (err.name === 'TokenExpiredError') {
      return res.status(401).json({ error: 'Token expired' });
    }
    if (err.name === 'JsonWebTokenError') {
      return res.status(401).json({ error: 'Invalid token' });
    }
    // Unexpected errors (e.g. algorithm mismatch) shouldn't leak details
    res.status(500).json({ error: 'Authentication error' });
  }
}

module.exports = authMiddleware;
```

**Changes made:**
- **Removed the manual expiry check** — `jwt.verify` uses `exp <= now` semantics internally, so tokens expiring exactly at the current second are correctly rejected
- **Differentiated error types** — `TokenExpiredError` vs `JsonWebTokenError` give clients actionable messages (e.g. a client can refresh on 401 expired but not on 401 invalid)
- **Added missing secret guard** — avoids `jwt.verify` accepting tokens signed with an empty secret if the env var is unset
- **Caught unexpected errors** — non-JWT errors (e.g. algorithm issues) return 500 without leaking internals
